using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using SolicitudIT_Isertec.Data;
namespace SolicitudIT_Isertec.Controllers;[Authorize(Roles="tecnico,admin")]public class CalendarioController:Controller{readonly AppDbContext db;public CalendarioController(AppDbContext db)=>this.db=db;public async Task<IActionResult> Index(){var x=await db.Solicitudes.Include(x=>x.Usuario).Include(x=>x.Tecnico).Where(x=>x.FechaProgramada.HasValue).OrderBy(x=>x.FechaProgramada).ThenBy(x=>x.HoraInicioProgramada).ToListAsync();return View(x);}}
